mapper.select:
SELECT 
FROM `paper` p
LEFT JOIN `course` c ON p.course_id = c.id
LEFT JOIN `user` u ON p.create_by = u.id

    AND p.create_by = #{createBy}

        AND p.course_id = #{courseId}


        AND p.status = #{status}


        AND p.paper_name LIKE CONCAT('%', #{keyword}, '%')


ORDER BY p.id DESC

SELECT FROM `paper` p LEFT JOIN `course` c ON p.course_id = c.id LEFT JOIN `user` u ON p.create_by = u.id WHERE p.status = 1 AND (p.start_time IS NULL OR p.start_time <= NOW()) AND (p.end_time IS NULL OR p.end_time >= NOW())
AND p.course_id = #{courseId}
ORDER BY p.id DESC
